use rand::Rng;
use rand_distr::{Distribution, Normal};
use statrs::statistics::Statistics;

// ─── Core Sleeping Beauty Model ───────────────────────────────────────────────

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Coin { Heads, Tails }

#[derive(Debug, Clone, Copy)]
struct Awakening { coin: Coin, day: Day }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Day { Monday, Tuesday }

impl Day {
    fn label(&self) -> &'static str {
        match self { Day::Monday => \"Mon\", Day::Tuesday => \"Tue\" }
    }
}

/// Simulation state: one run of the Sleeping Beauty experiment.
struct Trial {
    coin: Coin,
    awakenings: Vec<Awakening>,
}

impl Trial {
    fn run(rng: &mut impl Rng) -> Self {
        let coin = if rng.gen_bool(0.5) { Coin::Heads } else { Coin::Tails };
        let mut awakenings = vec"'![Awakening { coin, day: Day::Monday }];
        if coin == Coin::Tails {
            awakenings.push(Awakening { coin, day: Day::Tuesday });
        }
        Trial { coin, awakenings }
    }
}

// ─── Betting Frameworks ───────────────────────────────────────────────────────

/// Bet settled once per experiment (at the very end of the protocol).
/// Beauty bets $1 on Heads each time she is awakened; the bet is tallied and
/// settled only after the final awakening. The "once-per-trial" framing.
#[derive(Default)]
struct OncePerTrialBetting {
    total_bet: f64,
    total_payout: f64,
}

impl OncePerTrialBetting {
    fn record_awakening(&mut self, _awakening: &Awakening, odds: f64) {
        // Each awakening, Beauty places $1 on Heads at given odds.
        // Payout = $(1 + odds) if Heads, $0 if Tails.
        // Settlement is deferred to trial end; we aggregate.
        self.total_bet += 1.0;
    }

    fn settle(&mut self, coin: Coin, odds: f64) {
        // At trial end: if Heads, all accumulated bets pay out at (1+odds).
        if coin == Coin::Heads {
            self.total_payout += self.total_bet * (1.0 + odds);
        }
        // Tails: all bets are lost (pay nothing).
    }

    fn ev(&self) -> f64 { self.total_payout - self.total_bet }
}

/// Bet settled per awakening (immediate payout each time Beauty is woken).
/// Classic "Dutch book" framing used by thirders.
#[derive(Default)]
struct PerAwakeningBetting {
    total_bet: f64,
    total_payout: f64,
}

impl PerAwakeningBetting {
    fn record_awakening(&mut self, awakening: &Awakening, odds: f64) {
        self.total_bet += 1.0;
        if awakening.coin == Coin::Heads {
            self.total_payout += 1.0 + odds;
        }
    }

    fn ev(&self) -> f64 { self.total_payout - self.total_bet }
}

// ─── Monte Carlo Simulations ──────────────────────────────────────────────────

struct SimulationResult {
    half_ev: f64,    // EV under 1/2 credence betting strategy
    third_ev: f64,   // EV under 1/3 credence betting strategy
    empirical_p_heads_given_awakening: f64,
    trials: u64,
    total_awakenings: u64,
}

fn simulate(n_trials: u64) -> SimulationResult {
    let mut rng = rand::thread_rng();
    let mut total_awakenings = 0u64;
    let mut heads_awakenings = 0u64;

    // --- 1/2 camp: bet at fair-coin odds (1:1) settled once per trial ---
    let fair_odds = 1.0; // even money: $1 wins $1
    let mut once_bet = OncePerTrialsBetting::default();

    // --- 1/3 camp: bet at awakening-odds (2:1) settled per awakening ---
    let third_odds = 2.0; // 2:1 — "fair" if P(Heads) = 1/3
    let mut per_awake_bet = PerAwakeningBetting::default();

    for _ in 0..n_trials {
        let trial = Trial::run(&mut rng);
        for awakening in &trial.awakenings {
            total_awakenings += 1;
            if awakening.coin == Coin::Heads {
                heads_awakenings += 1;
            }
            once_bet.record_awakening(awakening, fair_odds);
            per_awake_bet.record_awakening(awakening, third_odds);
        }
        once_bet.settle(trial.coin, fair_odds);
    }

    SimulationResult {
        half_ev: once_bet.ev(),
        third_ev: per_awake_bet.ev(),
        empirical_p_heads_given_awakening: heads_awakenings as f64 / total_awakenings as f64,
        trials: n_trials,
        total_awakenings,
    }
}

// ─── Statistical Power Analysis for Lab Protocol ──────────────────────────────

/// Power analysis using normal approximation.
/// Compute required N to detect a difference between two proportions
/// at significance level alpha and power 1 - beta.
fn required_sample_size(p1: f64, p2: f64, alpha: f64, power: f64) -> f64 {
    // Cohen'"'s h = 2 * |arcsin(sqrt(p1)) - arcsin(sqrt(p2))|
    let h = 2.0 * (p1.sqrt().asin() - p2.sqrt().asin()).abs();
    let z_alpha = norm_ppf(1.0 - alpha / 2.0); // two-tailed
    let z_beta = norm_ppf(power);
    ((z_alpha + z_beta) / h).powi(2) * 2.0
}

